// ================= CONFIG (edit here) =================
// Group names must be lowercase. Members are Slack member IDs (start with U).
const GROUPS = {
  'team-all': [
    'U08AYDL2FQD',  // Alex
    'U06AE2KHEQ3',  // Alex Vi
  ],
  // 'team-it': ['U0000000001', 'U0000000002'],
};
const ALLOWED_CHANNELS = [];   // e.g. ['C0123456789']. Empty = any channel the app is in.
const EXPECTED_APP_ID = '';    // optional: Slack app ID (Basic Information page). Empty = skip check.
const PING_SENDER = false;     // false = don't tag the person who wrote the message
// =======================================================

const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || {};
const event = body.event || {};

// Ignore Slack retries (prevents duplicate pings)
if (headers['x-slack-retry-num']) return [];

// Optional sanity check that the event came from your app
if (EXPECTED_APP_ID && body.api_app_id !== EXPECTED_APP_ID) return [];

// Only plain user messages: skip edits, bot messages, joins, etc.
if (event.type !== 'message' || event.subtype || event.bot_id) return [];

const channel = event.channel || '';
if (ALLOWED_CHANNELS.length && !ALLOWED_CHANNELS.includes(channel)) return [];

const text = event.text || '';
const sender = event.user || '';

// Find @group-name in the text, but only for groups that actually exist.
// Unknown names (typos, normal words) are ignored silently.
const names = new Set();
for (const m of text.matchAll(/(?:^|[\s(])@([a-z0-9][a-z0-9_-]*)/gi)) {
  const name = m[1].toLowerCase();
  if (GROUPS[name]) names.add(name);
}
if (names.size === 0) return [];

// Combine members of all mentioned groups, no duplicates
const members = new Set();
for (const n of names) for (const id of GROUPS[n]) members.add(id);
if (!PING_SENDER) members.delete(sender);
if (members.size === 0) return [];

const label = [...names].map(n => `@${n}`).join(', ');
const mentions = [...members].map(id => `<@${id}>`).join(' ');
const count = members.size;

return [{
  json: {
    channel,
    sender,
    threadTs: event.thread_ts || event.ts || '',
    mentionText: `:mega: *${label}* (${count} ${count === 1 ? 'member' : 'members'})\n${mentions}\n\n> _Requested by <@${sender}> in <#${channel}>_`
  }
}];
